#include "stdlib/blas/ext/base/dcartesianproduct.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Computes the Cartesian product for two double-precision floating-point strided arrays.
*
* @param M           number of indexed elements of X
* @param N           number of indexed elements of Y
* @param X           first input array
* @param strideX     stride length for X
* @param Y           second input array
* @param strideY     stride length for Y
* @param Out         output array
* @param strideOut1  stride length between consecutive output pairs
* @param strideOut2  stride length between elements of each output pair
*/
void API_SUFFIX(stdlib_strided_dcartesian_product)( const CBLAS_INT M, const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const double *Y, const CBLAS_INT strideY, double *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2 ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( M, strideX );
	CBLAS_INT oy = stdlib_strided_stride2offset( N, strideY );
	CBLAS_INT oo = stdlib_strided_stride2offset( M*N, strideOut1 ) + stdlib_strided_stride2offset( 2, strideOut2 );
	API_SUFFIX(stdlib_strided_dcartesian_product_ndarray)( M, N, X, strideX, ox, Y, strideY, oy, Out, strideOut1, strideOut2, oo );
}

/**
* Computes the Cartesian product for two double-precision floating-point strided arrays using alternative indexing semantics.
*
* @param M           number of indexed elements of X
* @param N           number of indexed elements of Y
* @param X           first input array
* @param strideX     stride length for X
* @param offsetX     starting index for X
* @param Y           second input array
* @param strideY     stride length for Y
* @param offsetY     starting index for Y
* @param Out         output array
* @param strideOut1  stride length between consecutive output pairs
* @param strideOut2  stride length between elements of each output pair
* @param offsetOut   starting index for Out
*/
void API_SUFFIX(stdlib_strided_dcartesian_product_ndarray)( const CBLAS_INT M, const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY, double *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2, const CBLAS_INT offsetOut ) {
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT io;
	CBLAS_INT i;
	CBLAS_INT j;
	double v;

	if ( M <= 0 || N <= 0 ) {
		return;
	}
	ix = offsetX;
	io = offsetOut;
	for ( i = 0; i < M; i++ ) {
		v = X[ ix ];
		iy = offsetY;
		for ( j = 0; j < N; j++ ) {
			Out[ io ] = v;
			Out[ io + strideOut2 ] = Y[ iy ];
			io += strideOut1;
			iy += strideY;
		}
		ix += strideX;
	}
}
